-- ── hand-written: importing, matching, unmatching ───────────────────────────────────────────────
-- Not for the app to call. Whoever reconciles is the owner or an accountant who works in every
-- branch (a bank account is the whole company's, and reconciling reads every entry in it), the
-- account is a bank account in use, and it is held so that it is not archived meanwhile.
CREATE FUNCTION app.bank_reconcile_may(p_account uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF app.tenant_id() IS NULL OR app.current_user_id() IS NULL OR app.tenant_role() IS NULL OR app.tenant_role() NOT IN ('owner', 'accountant')
     OR app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'a bank account is reconciled by the owner or an accountant who works across the whole company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  PERFORM 1 FROM public.accounts a
    WHERE a.tenant_id = app.tenant_id() AND a.id = p_account AND a.control_type = 'bank' AND NOT a.is_group AND a.archived_at IS NULL
    FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'choose one of the company''s bank accounts that is in use' USING ERRCODE = 'SE360';
  END IF;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.bank_reconcile_may(uuid) FROM PUBLIC;
--> statement-breakpoint
-- A statement as the app read it from the bank's file: its lines (date, description, reference,
-- amount in or out, balance, fingerprint), and the balances the file gives. A line already
-- imported, from this file or another, is not imported again; a file with nothing new is refused.
CREATE FUNCTION app.import_bank_statement(p_account uuid, p_file_name text, p_layout text, p_lines jsonb, p_opening numeric, p_closing numeric) RETURNS jsonb
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_me uuid := app.current_user_id();
  v_id uuid := gen_random_uuid();
  v_count integer;
  v_added integer;
  v_from date;
  v_to date;
  v_bad integer;
BEGIN
  PERFORM app.bank_reconcile_may(p_account);
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 5000 THEN
    RAISE EXCEPTION 'a statement has from 1 to 5,000 lines' USING ERRCODE = 'SE361';
  END IF;
  -- Read once, here, from the lines as given; nothing is kept between calls.
  WITH given AS (
    SELECT x.ordinality::integer AS line_no, (x.value ->> 'date')::date AS line_date, (x.value ->> 'amount')::numeric AS amount, x.value ->> 'fingerprint' AS fingerprint
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS x(value, ordinality)
  )
  SELECT count(*), min(g.line_date), max(g.line_date),
         count(*) FILTER (WHERE g.line_date IS NULL OR g.amount IS NULL OR g.amount = 0 OR g.fingerprint IS NULL) + (count(*) - count(DISTINCT g.fingerprint))
    INTO v_count, v_from, v_to, v_bad FROM given g;
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'every line has a day, an amount and a fingerprint of its own' USING ERRCODE = 'SE361';
  END IF;
  INSERT INTO public.bank_statements (id, tenant_id, account_id, file_name, layout, line_count, added_count, period_from, period_to, opening_balance, closing_balance, imported_by)
    VALUES (v_id, v_tenant, p_account, left(btrim(p_file_name), 200), p_layout, v_count, 0, v_from, v_to, p_opening, p_closing, v_me);
  INSERT INTO public.bank_statement_lines (tenant_id, statement_id, account_id, line_no, line_date, description, reference, amount, balance, fingerprint)
    SELECT v_tenant, v_id, p_account, x.ordinality::integer, (x.value ->> 'date')::date, left(coalesce(x.value ->> 'description', ''), 500),
           left(nullif(btrim(x.value ->> 'reference'), ''), 60), (x.value ->> 'amount')::numeric, (x.value ->> 'balance')::numeric, x.value ->> 'fingerprint'
    FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS x(value, ordinality)
    ORDER BY x.ordinality
    ON CONFLICT (tenant_id, account_id, fingerprint) DO NOTHING;
  GET DIAGNOSTICS v_added = ROW_COUNT;
  IF v_added = 0 THEN
    RAISE EXCEPTION 'every line of this file was imported before' USING ERRCODE = 'SE362';
  END IF;
  UPDATE public.bank_statements b SET added_count = v_added WHERE b.tenant_id = v_tenant AND b.id = v_id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_me, app.tenant_role(), 'bank_statement.import', 'bank_statement', v_id,
      jsonb_build_object('account', p_account, 'file', left(btrim(p_file_name), 200), 'layout', p_layout, 'from', v_from, 'to', v_to, 'lines', v_count, 'added', v_added));
  RETURN jsonb_build_object('id', v_id, 'lines', v_count, 'added', v_added);
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.import_bank_statement(uuid, text, text, jsonb, numeric, numeric) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.import_bank_statement(uuid, text, text, jsonb, numeric, numeric) TO app_runtime;
--> statement-breakpoint
-- Statement lines and journal lines of one bank account found to be the same money: what the
-- bank says came in or went out adds up to what the books say. Either side may be empty only when
-- the other adds up to nil (an entry and its reversal; a bank's error and its correction).
CREATE FUNCTION app.match_bank_lines(p_account uuid, p_statement_lines uuid[], p_journal_lines uuid[], p_rule text) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_me uuid := app.current_user_id();
  v_id uuid := gen_random_uuid();
  v_statement uuid[] := coalesce(p_statement_lines, '{}');
  v_journal uuid[] := coalesce(p_journal_lines, '{}');
  v_found integer;
  v_bank numeric;
  v_books numeric;
BEGIN
  PERFORM app.bank_reconcile_may(p_account);
  IF p_rule IS NULL OR p_rule NOT IN ('reference', 'amount_date', 'by_hand') THEN
    RAISE EXCEPTION 'how the lines were matched' USING ERRCODE = 'SE363';
  END IF;
  IF cardinality(v_statement) + cardinality(v_journal) = 0 OR cardinality(v_statement) + cardinality(v_journal) > 500
     OR (SELECT count(DISTINCT x) FROM unnest(v_statement) x) <> cardinality(v_statement)
     OR (SELECT count(DISTINCT x) FROM unnest(v_journal) x) <> cardinality(v_journal) THEN
    RAISE EXCEPTION 'choose the lines to match, each once' USING ERRCODE = 'SE363';
  END IF;
  -- Held, in their order, so two people never match the same line.
  PERFORM 1 FROM public.bank_statement_lines l WHERE l.tenant_id = v_tenant AND l.id = ANY (v_statement) ORDER BY l.id FOR UPDATE;
  SELECT count(*), coalesce(sum(l.amount), 0) INTO v_found, v_bank FROM public.bank_statement_lines l
    WHERE l.tenant_id = v_tenant AND l.id = ANY (v_statement) AND l.account_id = p_account;
  IF v_found <> cardinality(v_statement) THEN
    RAISE EXCEPTION 'a statement line is not this account''s' USING ERRCODE = 'SE363';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bank_statement_lines l WHERE l.tenant_id = v_tenant AND l.id = ANY (v_statement) AND l.match_id IS NOT NULL) THEN
    RAISE EXCEPTION 'a statement line is matched already' USING ERRCODE = 'SE364';
  END IF;
  SELECT count(*), coalesce(sum(l.debit - l.credit), 0) INTO v_found, v_books FROM public.journal_lines l
    WHERE l.tenant_id = v_tenant AND l.id = ANY (v_journal) AND l.account_id = p_account;
  IF v_found <> cardinality(v_journal) THEN
    RAISE EXCEPTION 'an entry in the books is not this account''s' USING ERRCODE = 'SE363';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bank_match_journal_lines m WHERE m.tenant_id = v_tenant AND m.journal_line_id = ANY (v_journal)) THEN
    RAISE EXCEPTION 'an entry in the books is matched already' USING ERRCODE = 'SE364';
  END IF;
  IF v_bank <> v_books OR ((cardinality(v_statement) = 0 OR cardinality(v_journal) = 0) AND (v_bank <> 0 OR v_books <> 0 OR cardinality(v_statement) + cardinality(v_journal) < 2)) THEN
    RAISE EXCEPTION 'the lines do not add up to the same: the bank says %, the books %', v_bank, v_books USING ERRCODE = 'SE365';
  END IF;
  INSERT INTO public.bank_matches (id, tenant_id, account_id, rule, amount, matched_by) VALUES (v_id, v_tenant, p_account, p_rule, v_books, v_me);
  UPDATE public.bank_statement_lines l SET match_id = v_id WHERE l.tenant_id = v_tenant AND l.id = ANY (v_statement);
  -- A journal line matched meanwhile by someone else is refused here, by its unique index.
  INSERT INTO public.bank_match_journal_lines (tenant_id, match_id, journal_line_id, account_id)
    SELECT v_tenant, v_id, x, p_account FROM unnest(v_journal) x;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_me, app.tenant_role(), 'bank_match.match', 'bank_match', v_id,
      jsonb_build_object('account', p_account, 'rule', p_rule, 'amount', v_books::text, 'statementLines', cardinality(v_statement), 'entries', cardinality(v_journal)));
  RETURN v_id;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.match_bank_lines(uuid, uuid[], uuid[], text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.match_bank_lines(uuid, uuid[], uuid[], text) TO app_runtime;
--> statement-breakpoint
-- A match taken back: its lines are unmatched again.
CREATE FUNCTION app.unmatch_bank(p_match uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_match public.bank_matches%ROWTYPE;
BEGIN
  SELECT m.* INTO v_match FROM public.bank_matches m WHERE m.tenant_id = v_tenant AND m.id = p_match FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such match in this company' USING ERRCODE = 'SE366';
  END IF;
  PERFORM app.bank_reconcile_may(v_match.account_id);
  UPDATE public.bank_statement_lines l SET match_id = NULL WHERE l.tenant_id = v_tenant AND l.match_id = p_match;
  DELETE FROM public.bank_match_journal_lines m WHERE m.tenant_id = v_tenant AND m.match_id = p_match;
  DELETE FROM public.bank_matches m WHERE m.tenant_id = v_tenant AND m.id = p_match;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before)
    VALUES (v_tenant, app.current_user_id(), app.tenant_role(), 'bank_match.unmatch', 'bank_match', p_match,
      jsonb_build_object('account', v_match.account_id, 'rule', v_match.rule, 'amount', v_match.amount::text, 'matchedAt', v_match.matched_at, 'matchedBy', v_match.matched_by));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.unmatch_bank(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.unmatch_bank(uuid) TO app_runtime;
--> statement-breakpoint
-- A statement imported by mistake is removed, while nothing in it is matched.
CREATE FUNCTION app.delete_bank_statement(p_statement uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_statement public.bank_statements%ROWTYPE;
BEGIN
  SELECT s.* INTO v_statement FROM public.bank_statements s WHERE s.tenant_id = v_tenant AND s.id = p_statement FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such statement in this company' USING ERRCODE = 'SE366';
  END IF;
  PERFORM app.bank_reconcile_may(v_statement.account_id);
  -- Held: nobody matches one of its lines meanwhile.
  PERFORM 1 FROM public.bank_statement_lines l WHERE l.tenant_id = v_tenant AND l.statement_id = p_statement ORDER BY l.id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.bank_statement_lines l WHERE l.tenant_id = v_tenant AND l.statement_id = p_statement AND l.match_id IS NOT NULL) THEN
    RAISE EXCEPTION 'some of its lines are matched; unmatch them first' USING ERRCODE = 'SE367';
  END IF;
  DELETE FROM public.bank_statement_lines l WHERE l.tenant_id = v_tenant AND l.statement_id = p_statement;
  DELETE FROM public.bank_statements s WHERE s.tenant_id = v_tenant AND s.id = p_statement;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before)
    VALUES (v_tenant, app.current_user_id(), app.tenant_role(), 'bank_statement.delete', 'bank_statement', p_statement,
      jsonb_build_object('account', v_statement.account_id, 'file', v_statement.file_name, 'from', v_statement.period_from, 'to', v_statement.period_to, 'added', v_statement.added_count));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.delete_bank_statement(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.delete_bank_statement(uuid) TO app_runtime;
--> statement-breakpoint

