-- The audit rows only the functions above write.
CREATE FUNCTION app.audit_reserved_bank_statement(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('bank_statement.import', 'bank_statement.delete') $$;
--> statement-breakpoint
CREATE FUNCTION app.audit_reserved_bank_match(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('bank_match.match', 'bank_match.unmatch') $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.audit_reserved_bank_statement(text), app.audit_reserved_bank_match(text) FROM PUBLIC;
